def traduz(c, L):
    if L == 'pt': return c
    s = c
    for a, b in FRASES[L]:
        s = s.replace(a, b)
    if L == 'en':
        s = re.sub(r'(\d),(\d)', r'\1.\2', s); s = re.sub(r'^de ', '', s); s = re.sub(r'^Por ', 'For ', s); s = re.sub(r'^por ', 'for ', s)
    return s.strip()
